export function walkFuelCommonsOfCensus (census) {
  if (!census || typeof census !== 'object' || Array.isArray(census)) return 0
  const walk = census.walk
  if (!walk || typeof walk !== 'object' || Array.isArray(walk)) return 0
  const byLane = walk.byLane
  if (!byLane || typeof byLane !== 'object' || Array.isArray(byLane)) return 0
  if (!Object.prototype.hasOwnProperty.call(byLane, CELL)) return 0
  const n = byLane[CELL]
  return Number.isInteger(n) && n >= 0 ? n : 0
}

